from flask import Flask, request, jsonify, send_file
import os

app = Flask(__name__)

REPO_BASE_PATH = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "data", "repo_clones"))

@app.route('/get-file', methods=['POST'])
def get_file():
    file_path = request.json.get('file_path')
    if not file_path:
        return jsonify({"error": "File path not provided"}), 400

    full_path = os.path.join(REPO_BASE_PATH, file_path)
    if not os.path.exists(full_path):
        return jsonify({"error": f"File not found: {file_path}"}), 404

    try:
        return send_file(full_path, as_attachment=True)
    except Exception as e:
        return jsonify({"error": f"Failed to retrieve file: {str(e)}"}), 500

@app.route('/list-files', methods=['GET'])
def list_files():
    repo_name = request.args.get('repo_name', '')
    repo_path = os.path.join(REPO_BASE_PATH, repo_name)

    if not os.path.exists(repo_path):
        return jsonify({"error": f"Repository not found: {repo_name}"}), 404

    file_list = []
    for root, _, files in os.walk(repo_path):
        for file in files:
            file_list.append(os.path.relpath(os.path.join(root, file), REPO_BASE_PATH))

    return jsonify({"files": file_list}), 200

