import React, { useState } from "react";

const App = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");

  const handleSend = async () => {
    if (input.startsWith("/")) {
      await onCommand(input);
    } else {
      // Handle regular chat messages
      setMessages([...messages, { role: "user", content: input }]);
      setInput("");
    }
  };

  const onCommand = async (command) => {
    try {
      if (command.startsWith("/get-file")) {
        const [, filePath] = command.split(" ");
        const response = await fetch("http://localhost:8000/get-file", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ file_path: filePath }),
        });

        if (!response.ok) {
          const error = await response.json();
          setMessages([...messages, { role: "system", content: `Error: ${error.detail}` }]);
        } else {
          const fileContent = await response.text();
          setMessages([...messages, { role: "system", content: `File Content:\n${fileContent}` }]);
        }
      } else if (command.startsWith("/list-files")) {
        const [, repoName] = command.split(" ");
        const response = await fetch(`http://localhost:8000/list-files?repo_name=${repoName}`);

        if (!response.ok) {
          const error = await response.json();
          setMessages([...messages, { role: "system", content: `Error: ${error.detail}` }]);
        } else {
          const data = await response.json();
          const fileList = data.files.join("\n");
          setMessages([...messages, { role: "system", content: `Files:\n${fileList}` }]);
        }
      } else {
        setMessages([...messages, { role: "system", content: `Unknown command: ${command}` }]);
      }
    } catch (error) {
      setMessages([...messages, { role: "system", content: `Error executing command: ${error.message}` }]);
    }
    setInput("");
  };

  return (
    <div className="chat-container">
      <div className="messages">
        {messages.map((msg, index) => (
          <div key={index} className={`message ${msg.role}`}>
            {msg.content}
          </div>
        ))}
      </div>
      <div className="input-container">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Type a message or /command..."
        />
        <button onClick={handleSend}>Send</button>
      </div>
    </div>
  );
};

export default App;
```

