from fastapi import FastAPI, HTTPException
import os

app = FastAPI()

# Use the dynamically set REPO_BASE_PATH
REPO_BASE_PATH = os.getenv(
    "REPO_BASE_PATH",
    os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "data", "repo_clones"))  # Default for local development
)

@app.get("/list-files")
async def list_files(repo_name: str):
    repo_path = os.path.join(REPO_BASE_PATH, repo_name)

    if not os.path.exists(repo_path):
        raise HTTPException(status_code=404, detail=f"Repository '{repo_name}' not found")

    try:
        files = [f for f in os.listdir(repo_path) if os.path.isfile(os.path.join(repo_path, f))]
        return {"files": files}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
